//! Actual SELECT construction preserves native option ownership and nearby App state.
use super::*;
struct Fixture(std::path::PathBuf);
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut pending=vec![0];while let Some(n)=pending.pop(){if app.document.attr(n,"id")==Some(id){return n;}pending.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}
#[test]
fn range_fragment_controls_actual_app_trusted_construction_and_checkbox_keep_editor_paint_links(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-range-fragment-controls-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><html><head><style>body{margin:0;background:white}#paint{position:absolute;left:20px;top:20px;width:120px;height:32px;background:#114455}#paint.ready{background:#228844}#go{position:absolute;left:220px;top:20px;width:160px;height:32px}#menu{position:absolute;left:20px;top:80px;width:150px;height:30px}#newmenu{position:absolute;left:20px;top:130px;width:150px;height:30px}#neighbor{position:absolute;left:220px;top:100px;width:180px;height:30px}#stable{position:absolute;left:420px;top:100px}</style></head><body><div id=paint>Indicator</div><div id=mount></div><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><button id=go type=button>Construct select</button><div id=destination></div><script>
var mount=document.getElementById('mount'),watch=new MutationObserver(function(){});watch.observe(mount,{childList:true});document.getElementById('go').onclick=function(e){if(!e.isTrusted)throw 'actual pointer';var r=document.createRange();r.selectNodeContents(mount);var fragment=r.createContextualFragment('<input id=ftext value=Initial style="position:absolute;left:20px;top:80px;width:150px;height:30px"><input id=fcheck type=checkbox checked style="position:absolute;left:20px;top:130px;width:20px;height:20px"><textarea id=farea style="position:absolute;left:20px;top:170px;width:150px;height:50px">First&amp;line</textarea><select id=fchoice style="position:absolute;left:20px;top:240px;width:150px;height:30px"><optgroup disabled><option value=a>A<hr><option value=b selected>B</select>'),text=fragment.childNodes[0],check=fragment.childNodes[1],area=fragment.childNodes[2],choice=fragment.childNodes[3];if(text.value!=='Initial'||!check.checked||area.value!=='First&line'||choice.value!=='b'||text.ownerDocument!==document||text.isConnected||document.getElementById('ftext')!==null||watch.takeRecords().length)throw 'native detached defaults';text.value='edited before connection';area.value='edited area';mount.appendChild(fragment);if(fragment.firstChild!==null||mount.childNodes.length!==4||mount.firstChild!==text||text.value!=='edited before connection'||area.value!=='edited area'||!text.isConnected||document.getElementById('fchoice')!==choice||choice.value!=='b'||choice.selectedIndex!==1)throw 'native connection state and identity';var records=watch.takeRecords();if(records.length!==1||records[0].target!==mount||records[0].addedNodes.length!==4||records[0].addedNodes[0]!==text||records[0].addedNodes[3]!==choice)throw 'actual native control publication';check.onchange=function(e){if(!e.isTrusted||this.checked||this!==document.getElementById('fcheck'))throw 'actual native checkbox change';document.title='Range controls clicked';};if(document.getElementById('neighbor').value!=='edited neighbor')throw 'native neighbor';document.getElementById('paint').className='ready';document.title='Range controls preserved';};
</script></body></html>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0);
 let before=app.draw();assert_eq!(before.pixels[(app.content_top()+40)as usize*before.width+110],0x114455);
 let go=node(&app,"go");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let scroll=app.scroll;
 let rect=app.page.controls.iter().find(|r|r.node==go).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);
 assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert_eq!(app.document.title,"Range controls preserved");let text=node(&app,"ftext");let area=node(&app,"farea");let check=node(&app,"fcheck");let choice=node(&app,"fchoice");assert_eq!(app.forms.controls[&text].value.text(),"edited before connection");assert_eq!(app.forms.controls[&area].value.text(),"edited area");assert!(app.forms.controls[&check].checked);let state=app.forms.controls[&choice].select.as_ref().unwrap();assert_eq!(state.options.len(),2);assert!(state.options[0].disabled);assert!(!state.options[1].disabled);assert_eq!(state.options[1].group,None);assert_eq!(state.selected,Some(1));assert_eq!(state.rows.len(),3);for n in [text,area,check,choice]{assert!(app.page.controls.iter().any(|r|r.node==n));}
 let rect=app.page.controls.iter().find(|r|r.node==check).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);assert!(!app.forms.controls[&check].checked);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert_eq!(app.document.title,"Range controls clicked");
 let painted=app.draw();assert_eq!(painted.pixels[(app.content_top()+40)as usize*painted.width+110],0x228844);let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!(app.raw,raw);assert_eq!(app.location,location);assert_eq!(app.script_epoch,epoch);assert_eq!(app.scroll,scroll);
}
